static int i2c_check_addr_busy(struct i2c_adapter *adapter, int addr) /* <=== i2c_check_addr_busy */ 
{
	struct i2c_adapter *parent = i2c_parent_is_i2c_adapter(adapter);
	int result = 0;

	if (parent)
		result = i2c_check_mux_parents(parent, addr);

	if (!result)
		result = device_for_each_child(&adapter->dev, &addr,
						i2c_check_mux_children);

	return result;
}

size_t __weak strlcpy(char *dest, const char *src, size_t size) /* <=== strlcpy */ 
{
	size_t ret = strlen(src);

	if (size) {
		size_t len = (ret >= size) ? size - 1 : ret;
		memcpy(dest, src, len);
		dest[len] = '\0';
	}
	return ret;
}

